const listInvoicesForUser = `-- name: ListInvoicesForUser :many
SELECT o.id, o.buyer_id, o.seller_id, o.product_id, o.currency_code, o.amount, o.commission_amount, o.commission_percent, o.status, o.auto_release_at, o.released_at, o.released_by, o.invoice_title, o.invoice_description, o.cancel_reason, o.cancelled_by, o.created_at, o.updated_at, bu.username AS buyer_username, su.username AS seller_username
FROM orders o
JOIN users bu ON bu.id = o.buyer_id
JOIN users su ON su.id = o.seller_id
WHERE o.invoice_title IS NOT NULL
  AND (o.buyer_id = $1::uuid OR o.seller_id = $1::uuid)
  AND (
    $2::text = ''
    OR ($2::text = 'buyer'  AND o.buyer_id  = $1::uuid)
    OR ($2::text = 'seller' AND o.seller_id = $1::uuid)
  )
  AND (
    $3::text = ''
    OR o.status = $3::text
  )
  AND (
    $4::text = ''
    OR (length($4::text) = 36 AND o.id = $4::uuid)
    OR (length($4::text) != 36 AND o.id::text ILIKE '%' || $4::text || '%')
  )
ORDER BY o.created_at DESC, o.id DESC
LIMIT $6 OFFSET $5
`

